function emptyState(draft){return `<div class="empty-state"><div class="empty-icon">${icon(state.query?'"'search':draft?'edit':state.view==='Starred'?'star':'inbox')}</div><h3>"'${state.query?'"'No conversations found':draft?'A blank page, a fresh idea.':state.view==='Inbox'?'You’re all caught up.':'Nothing here just yet.'}</h3><p>"'${state.query?'"'Try another keyword, sender, or search filter.':draft?'Start a message. We’ll save it as you go.':'Your next conversation is just around the corner.'}</p><button class=\"primary-button\" data-action=\""'${state.query?'"'close-search':'compose'}\">"'${state.query?'"'Clear search':'Write a message'}</button></div>"'`;}
function reader(){const m=state.mail.find(m=>m.id===state.open);if(!m){state.open=null;return mailbox();}return `<div class="reader-toolbar"><button class="icon-btn" data-action="back" aria-label="Back to mailbox">${icon('"'back')}</button><span class=\"toolbar-separator\"></span>"'${btn('"'archive','Archive conversation')}"'${btn('"'trash',m.folder==='trash'?'Delete permanently':'Delete conversation')}"'${btn('"'mail','Mark as unread')}"'${btn('"'clock','Snooze conversation')}"'${btn('"'label','Label conversation')}"'${btn('"'more','More actions')}<div class=\"reader-toolbar-end\"><span>"'${filtered().findIndex(x=>x.id===m.id)+1} of ${filtered().length}</span><button class="icon-btn" data-action="previous-message" aria-label="Previous conversation">${icon('"'chevron','flip')}</button><button class=\"icon-btn\" data-action=\"next-message\" aria-label=\"Next conversation\">"'${icon('"'chevron')}</button></div></div><div class=\"conversation\"><div class=\"conversation-heading\"><h2>"'${esc(m.subject)}</h2><button class="star-button ${m.starred?'"'starred':''}\" data-action=\"star\" data-id=\""'${m.id}" aria-label="${m.starred?'"'Unstar':'Star'} conversation\">"'${icon('"'star')}</button></div><div class=\"conversation-labels\"><span class=\"neutral-badge\">"'${m.folder==='"'inbox'?'Inbox':m.folder==='sent'?'Sent':m.folder==='archive'?'Archived':m.folder==='trash'?'Trash':'Snoozed'}</span>"'${m.labels.map(labelBadge).join('"'')}"'${m.folder==='"'trash'?'<button class=\"text-button\" data-action=\"restore\">Restore to inbox</button>':''}</div>"'${m.thread.map((t,i)=>`<details class="thread-collapsed"><summary>${avatar(t)}<div><strong>${esc(t.sender)}</strong><span>${esc(t.body.slice(0,80).replaceAll('"'\\n',' '))}…</span></div><time>"'${esc(t.time)}</time>${icon('"'down')}</summary><div class=\"thread-body\">"'${esc(t.body).replaceAll('"'\\n','<br>')}</div></details>"'`).join('"'')}<section class=\"message-card\"><div class=\"message-header\">"'${avatar(m,true)}<div class="message-author"><strong>${esc(m.folder==='"'sent'?'Alex Morgan':m.sender)}</strong><span class=\"author-email\">&lt;"'${esc(m.folder==='"'sent'?'alex@studio.co':m.email)}&gt;</span><div class=\"message-to\">to "'${m.folder==='"'sent'?esc(m.email):'me'} <button data-action=\"message-details\" class=\"tiny-button\" aria-label=\"Message details\">"'${icon('"'down')}</button></div></div><time>"'${esc(m.time)}<span>Sep 30, 2026</span></time><button class="icon-btn" data-action="reply" aria-label="Reply">${icon('"'reply')}</button></div><div class=\"message-body\">"'${esc(m.body).replaceAll('"'\\n','<br>')}</div>"'${m.attachments.length?`<div class="message-attachments"><div class="attachment-heading">${icon('"'attach')}<strong>"'${m.attachments.length} attachment${m.attachments.length>1?'"'s':''}</strong><span>• Scanned for your peace of mind</span></div><div class=\"attachment-grid\">"'${m.attachments.map((a,i)=>`<button class="attachment-card" data-action="download" data-id="${m.id}" data-index="${i}"><div class="file-preview ${a.name.endsWith('"'.jpg')?'photo-preview':'pdf-preview'}\">"'${a.name.endsWith('"'.jpg')?'<span class=\"landscape-sun\"></span>':"'`<div class="paper"><span>STUDIO</span><i></i><i></i><i></i><i></i></div>`}</div><div class="file-info"><span class="file-type">${a.name.endsWith('"'.jpg')?'JPG':a.name.endsWith('.csv')?'CSV':'PDF'}</span><span><strong>"'${esc(a.name)}</strong><small>${a.size}</small></span>${icon('"'download')}</div></button>"'`).join('"'')}</div></div>"'`:'"''}<div class=\"reply-actions\"><button class=\"outline-button\" data-action=\"reply\">"'${icon('"'reply')} Reply</button><button class=\"outline-button\" data-action=\"reply-all\">"'${icon('"'users')} Reply all</button><button class=\"outline-button\" data-action=\"forward\">"'${icon('"'forward')} Forward</button></div></section></div>"'`;}
function composeContent(){const c=state.compose;return `<section class="compose-window ${c.expanded?'"'expanded':''} "'${c.minimized?'"'minimized':''}\" aria-label=\"Compose message\"><header class=\"compose-header\"><span>"'${icon('"'edit')} "'${c.replyTo?'"'Reply':'New message'}</span><div><button class=\"icon-btn\" data-action=\"minimize-compose\" aria-label=\"Minimize\">"'${icon('"'minus')}</button><button class=\"icon-btn\" data-action=\"expand-compose\" aria-label=\"Expand compose\">"'${icon('"'expand')}</button><button class=\"icon-btn\" data-action=\"close-compose\" aria-label=\"Save and close draft\">"'${icon('"'close')}</button></div></header><div class=\"compose-content\"><div class=\"recipient-line\"><label for=\"compose-to\">To</label><input id=\"compose-to\" name=\"to\" type=\"text\" autocomplete=\"off\" list=\"contacts\" placeholder=\"Recipients\" value=\""'${esc(c.to)}"><button class="text-button" data-action="toggle-cc">Cc</button><button class="text-button" data-action="toggle-bcc">Bcc</button></div><datalist id="contacts">${state.mail.filter(m=>m.folder==='"'inbox').map(m=>"'`<option value="${esc(m.email)}">${esc(m.sender)}</option>`).join('"'')}</datalist>"'${c.showCc?`<div class="recipient-line"><label for="compose-cc">Cc</label><input id="compose-cc" name="cc" value="${esc(c.cc||'"'')}\"></div>"'`:'"''}"'${c.showBcc?`<div class="recipient-line"><label for="compose-bcc">Bcc</label><input id="compose-bcc" name="bcc" value="${esc(c.bcc||'"'')}\"></div>"'`:'"''}<input class=\"subject-input\" id=\"compose-subject\" aria-label=\"Subject\" placeholder=\"Subject\" value=\""'${esc(c.subject)}"><textarea id="compose-body" aria-label="Message body" placeholder="Write something good…">${esc(c.body)}</textarea>${c.attachments.length?`<div class="compose-attachments">${c.attachments.map((a,i)=>`<span>${icon('"'file')} "'${esc(a.name)} <button class="tiny-button" data-action="remove-attachment" data-index="${i}" aria-label="Remove ${esc(a.name)}">${icon('"'close')}</button></span>"'`).join('"'')}</div>"'`:'"''}<div class=\"draft-status\"><span class=\"sync-dot\"></span> Saved to drafts</div><footer class=\"compose-footer\"><button class=\"send-button\" data-action=\"send-message\">Send "'${icon('"'send')}</button><div class=\"compose-tools\"><button class=\"icon-btn\" data-action=\"attach-file\" aria-label=\"Attach files\">"'${icon('"'attach')}</button><button class=\"icon-btn\" data-action=\"insert-link\" aria-label=\"Insert link\">"'${icon('"'link')}</button><button class=\"icon-btn\" data-action=\"insert-emoji\" aria-label=\"Insert emoji\">"'${icon('"'smile')}</button></div><span class=\"send-shortcut\">⌘ ↵</span><button class=\"icon-btn discard\" data-action=\"discard-compose\" aria-label=\"Discard draft\">"'${icon('"'trash')}</button></footer><input type=\"file\" id=\"file-input\" multiple hidden></div></section>"'`;}
function menuContent(){const type=state.menu;return `<div class="menu-scrim" data-action="dismiss-menu"></div><div class="dropdown ${type==='"'account'?'account-dropdown':type==='selection'?'selection-dropdown':''}\">"'${type==='"'label'?"'`<div class="dropdown-title">Label as</div>${state.labels.map(l=>{const targets=targetIds().map(id=>state.mail.find(m=>m.id===id)).filter(Boolean);return `<button data-action="apply-label" data-label="${esc(l.name)}"><span class="label-dot" style="--label-color:${l.color}"></span>${esc(l.name)}${targets.length&&targets.every(m=>m.labels.includes(l.name))?icon('"'check'):''}</button>"'`}).join('"'')}<div class=\"dropdown-divider\"></div><button data-action=\"new-label\">"'${icon('"'plus')} Create new label</button>"'`:type==='"'snooze'?"'`<div class="dropdown-title">Snooze until</div><button data-action="snooze" data-value="Later today">${icon('"'sun')} Later today <small>6:00 PM</small></button><button data-action=\"snooze\" data-value=\"Tomorrow\">"'${icon('"'coffee')} Tomorrow <small>8:00 AM</small></button><button data-action=\"snooze\" data-value=\"Next week\">"'${icon('"'calendar')} Next week <small>Monday</small></button>"'`:type==='"'account'?"'`<div class="account-card"><span class="profile big">AM</span><strong>Alex Morgan</strong><span>alex@studio.co</span><span class="account-local">Personal · Studio workspace</span></div><div class="dropdown-divider"></div><button data-action="settings">${icon('"'settings')} Account preferences</button><button data-action=\"help\">"'${icon('"'keyboard')} Keyboard shortcuts</button>"'`:type==='"'selection'?"'`<div class="dropdown-title">Select messages</div>${['"'All','None','Read','Unread','Starred'].map(x=>"'`<button data-action="select-type" data-value="${x}">${x}</button>`).join('"'')}"'`:`<div class="dropdown-title">Message actions</div><button data-action="mark-all-read">${icon('"'mail')} Mark "'${state.selected.size?'"'selected':'all'} as read</button><button data-action=\"toggle-read\">"'${icon('"'mail')} Mark as unread</button><button data-action=\"restore\">"'${icon('"'inbox')} Move to inbox</button><button data-action=\"help\">"'${icon('"'keyboard')} Keyboard shortcuts</button>"'`}</div>`;}
function modalContent(){const type=state.modal;return `<div class="modal-backdrop" data-action="dismiss-modal"><section class="modal ${type==='"'filters'?'search-modal':''}\" role=\"dialog\" aria-modal=\"true\" aria-label=\""'${esc(type)}" data-stop><header><h3>${{settings:'"'Make yourself at home',help:'A faster way to mail',filters:'Find just what you need','new-label':'Create a label',storage:'Your storage',details:'Message details','empty-trash':'Empty trash?'}[type]||type}</h3><button class=\"icon-btn\" data-action=\"dismiss-modal\" aria-label=\"Close dialog\">"'${icon('"'close')}</button></header>"'${type==='"'settings'?"'`<p class="modal-description">A few small changes. A space that feels like you.</p><h4>Appearance</h4><div class="setting-options"><button class="theme-choice ${state.settings.theme==='"'light'?'chosen':''}\" data-action=\"theme\" data-value=\"light\"><span class=\"theme-preview light-preview\"><i></i><b></b></span>Light "'${state.settings.theme==='"'light'?icon('check'):''}</button><button class=\"theme-choice "'${state.settings.theme==='"'dark'?'chosen':''}\" data-action=\"theme\" data-value=\"dark\"><span class=\"theme-preview dark-preview\"><i></i><b></b></span>Dark "'${state.settings.theme==='"'dark'?icon('check'):''}</button></div><h4>Inbox density</h4><div class=\"density-options\">"'${['"'comfortable','compact'].map(v=>"'`<button class="outline-button ${state.settings.density===v?'"'chosen':''}\" data-action=\"density\" data-value=\""'${v}">${v[0].toUpperCase()+v.slice(1)} ${state.settings.density===v?icon('"'check'):''}</button>"'`).join('"'')}</div><div class=\"settings-foot\">"'${icon('"'shield')} Your preferences are saved on this device.</div>"'`:type==='"'help'?"'`<p class="modal-description">Keep your hands on the keyboard.</p><div class="shortcut-list">${[['"'Compose a message','C'],['Search your mail','/'],['Back / close dialog','Esc'],['Archive selected','E'],['Star selected','S'],['Delete selected','#'],['Mark unread','U'],['Send a message','⌘ Enter']].map(([l,k])=>"'`<div><span>${l}</span><kbd>${k}</kbd></div>`).join('"'')}</div><div class=\"help-tip\">Search smarter with <code>from:sofia</code>, <code>is:unread</code>, <code>has:attachment</code>, or <code>label:Work</code>.</div>"'`:type==='"'filters'?"'`<form id="filter-form"><label>From<input name="from" placeholder="Name or email address"></label><label>Subject or keywords<input name="words" placeholder="What are you looking for?"></label><label>Label<select name="label"><option value="">Any label</option>${state.labels.map(l=>`<option>${esc(l.name)}</option>`).join('"'')}</select></label><div class=\"filter-checks\"><label><input name=\"unread\" type=\"checkbox\"> Unread only</label><label><input name=\"attachment\" type=\"checkbox\"> Has attachment</label></div><button class=\"primary-button\" type=\"submit\">"'${icon('"'search')} Search mail</button></form>"'`:type==='"'new-label'?"'`<p class="modal-description">Give your conversations a little structure.</p><form id="label-form"><label>Label name<input name="labelName" required maxlength="24" placeholder="e.g. Side projects" autofocus></label><label>Color<div class="color-options">${['"'#8b79df','#e6a758','#55a890','#6492cc','#d87592','#85929d'].map((c,i)=>"'`<label class="color-option" style="--label-color:${c}"><input type="radio" name="color" value="${c}" ${i===0?'"'checked':''}><span></span></label>"'`).join('"'')}</div></label><button class=\"primary-button\" type=\"submit\">Create label</button></form>"'`:type==='"'storage'?"'`<div class="storage-modal-icon">${icon('"'archive')}</div><h2>Plenty of room for what’s next.</h2><p>2.4 GB of your 15 GB workspace used.</p><div class=\"storage-bar\"><i></i></div><div class=\"storage-breakdown\"><span>Mail</span><strong>1.8 GB</strong><span>Attachments</span><strong>0.6 GB</strong><span>Available</span><strong>12.6 GB</strong></div><p class=\"modal-description\">Mailbox data is saved locally in your browser. Attachments you add stay on this device.</p>"'`:type==='"'empty-trash'?"'`<p>These ${state.mail.filter(m=>m.folder==='"'trash').length} conversations will be permanently removed.</p><button class=\"danger-button\" data-action=\"confirm-empty\">Empty trash</button>"'`:type==='"'details'?detailsContent():''}</section></div>"'`;}
function detailsContent(){const m=state.mail.find(m=>m.id===state.open);return m?`<dl class="message-details"><dt>From</dt><dd>${esc(m.sender)} &lt;${esc(m.email)}&gt;</dd><dt>To</dt><dd>Alex Morgan &lt;alex@studio.co&gt;</dd><dt>Date</dt><dd>${new Date(m.date).toLocaleString()}</dd><dt>Subject</dt><dd>${esc(m.subject)}</dd><dt>Security</dt><dd>${icon('"'shield')} Local mailbox</dd></dl>"'`:'"'';}
function railPanel(){const panel=state.rail;return "'`<aside class="rail-panel"><header><h3>${panel}</h3><button class="icon-btn" data-action="close-rail" aria-label="Close ${panel}">${icon('"'close')}</button></header>"'${panel==='"'Calendar'?"'`<div class="mini-calendar"><div class="month-title">September 2026 ${icon('"'calendar')}</div><div class=\"calendar-grid\">"'${['"'M','T','W','T','F','S','S'].map(d=>"'`<span class="weekday">${d}</span>`).join('"'')}"'${Array.from({length:35},(_,i)=>`<span class="${i===30?'"'today':''} "'${i<1||i>30?'"'muted-day':''}\">"'${i<1?31:i>30?i-30:i}</span>`).join('"'')}</div></div><h4>Today’s schedule</h4><div class=\"event-card\"><span>11:00 — 11:30</span><strong>Team check-in</strong><small>Studio · Meeting room</small></div><div class=\"event-card green-event\"><span>14:00 — 15:00</span><strong>Website design review</strong><small>With Sofia & Oliver</small></div><p class=\"panel-caption\">A little breathing room after 3 PM.</p>"'`:panel==='"'Notes'?"'`<p class="panel-caption">A thought, a reminder, a big idea.</p><textarea id="notes" aria-label="Personal notes" placeholder="Start writing…">${esc(state.notes)}</textarea><small class="notes-saved">Saved on this device</small>`:panel==='"'Tasks'?"'`<p class="panel-caption">One thing at a time.</p><form id="task-form"><input name="task" placeholder="Add a task" required><button class="icon-btn" aria-label="Add task">${icon('"'plus')}</button></form><div id=\"task-list\">"'${tasksContent()}</div>`:`<p class="panel-caption">The people in your corner.</p><div class="contact-list">${state.mail.filter(m=>m.category==='"'Primary'&&m.folder==='inbox').slice(0,9).map(m=>"'`<button data-action="contact-compose" data-id="${m.id}">${avatar(m)}<span><strong>${esc(m.sender)}</strong><small>${esc(m.email)}</small></span>${icon('"'mail')}</button>"'`).join('"'')}</div>"'`}</aside>`;}
function tasksContent(){return load('"'gpt6-tasks-v1',[{id:1,text:'Review website feedback',done:false},{id:2,text:'Book Friday team lunch',done:true},{id:3,text:'Send Q4 planning notes',done:false}]).map(t=>"'`<label class="task-item ${t.done?'"'done':''}\"><input type=\"checkbox\" data-action=\"task-check\" data-id=\""'${t.id}" ${t.done?'"'checked':''}><span>"'${esc(t.text)}</span><button class="tiny-button" data-action="task-delete" data-id="${t.id}" aria-label="Delete task">${icon('"'close')}</button></label>"'`).join('"'');}
function toast(message,undo=false){const el="'$('"'#toast');if("'!el)return;clearTimeout(toastTimer);el.innerHTML=`<span class="toast-icon">${icon('"'check')}</span><span>"'${esc(message)}</span>${undo?'"'<button data-action=\"undo\">Undo</button>':''}<button class=\"tiny-button\" data-action=\"dismiss-toast\" aria-label=\"Dismiss notification\">"'${icon('"'close')}</button>"'`;el.classList.add('"'show');toastTimer=setTimeout(()=>el.classList.remove('show'),5000);}
function targetIds(id){return id?[id]:state.open?[state.open]:[...state.selected];}
function mutate(ids,change,message){if("'!ids.length){toast('"'Select a conversation first.');return;}undoState={mail:structuredClone(state.mail),drafts:structuredClone(state.drafts)};state.mail=state.mail.map(m=>ids.includes(m.id)?change({...m}):m);state.selected.clear();state.menu=null;persist();render();if(message)toast(message,true);}
function saveDraft(){if("'!state.compose)return;const c=state.compose;if(!c.to&&!c.subject&&!c.body&&!c.attachments.length){state.drafts=state.drafts.filter(d=>d.id!==c.id);persist();return;}const d={...c,updated:'"'Just now'};state.drafts=state.drafts.filter(d=>d.id"'!==c.id);state.drafts.unshift(d);persist();}
function compose(initial={}){if(state.compose)saveDraft();state.compose={id:'"'draft-'+Date.now(),to:'',subject:'',body:'',attachments:[],...initial};state.menu=null;state.modal=null;saveDraft();render();(initial.body?"'$('"'#compose-body'):"'$('"'#compose-to'))?.focus();}
function navigate(view){saveDraft();state.view=view;state.open=null;state.selected.clear();state.query='';state.page=0;state.menu=null;state.drawer=false;state.unreadOnly=false;render();}
function openMessage(id){state.open=id;const m=state.mail.find(m=>m.id===id);if(m)m.unread=false;state.selected.clear();state.menu=null;persist();render();}
function perform(action,el){const id=el?.dataset.id;const ids=targetIds(id);switch(action){
case 'navigate':navigate(el.dataset.view);break;
case 'category':state.category=el.dataset.category;state.page=0;state.selected.clear();render();break;
case 'compose':compose();break;
case 'contact-compose':compose({to:state.mail.find(m=>m.id===id).email});break;
case 'open':openMessage(id);break;
case 'back':state.open=null;render();break;
case 'select':el.checked?state.selected.add(id):state.selected.delete(id);render();break;
case 'select-all':{const list=state.view==='Drafts'?state.drafts:filtered().slice(state.page*30,(state.page+1)*30);el.checked?list.forEach(m=>state.selected.add(m.id)):state.selected.clear();render();break;}
case 'selection-menu':state.menu='selection';render();break;
case 'select-type':state.selected.clear();(state.view==='Drafts'?state.drafts:filtered()).filter(m=>el.dataset.value==='All'||el.dataset.value==='Unread'&&m.unread||el.dataset.value==='Read'&&"'!m.unread||el.dataset.value==='"'Starred'&&m.starred).forEach(m=>state.selected.add(m.id));state.menu=null;render();break;
case 'star':mutate(ids,m=>({...m,starred:"'!m.starred}));break;
case '"'archive':{if(state.view==='Drafts'){toast('Drafts are saved until you send or discard them.');break;}const wasOpen="'!!state.open;state.open=null;mutate(ids,m=>({...m,folder:'"'archive'}),"'`${ids.length===1?'"'Conversation':'Conversations'} archived"'`);break;}
case '"'trash':if(state.view==='Drafts'){undoState={mail:structuredClone(state.mail),drafts:structuredClone(state.drafts)};state.drafts=state.drafts.filter(d=>"'!ids.includes(d.id));state.selected.clear();persist();render();toast('"'Drafts discarded',true);}else if(state.view==='Trash'){undoState={mail:structuredClone(state.mail),drafts:structuredClone(state.drafts)};state.mail=state.mail.filter(m=>"'!ids.includes(m.id));state.open=null;persist();render();toast('"'Conversation permanently deleted',true);}else {state.open=null;mutate(ids,m=>({...m,folder:'trash'}),'Moved to trash');}break;
case 'restore':state.open=null;mutate(ids,m=>({...m,folder:'inbox'}),'Moved to inbox');break;
case 'mail':case 'toggle-read':{const unread=action==='mail'?true:"'!state.mail.find(m=>ids.includes(m.id))?.unread;mutate(ids,m=>({...m,unread}),`Marked as ${unread?'"'unread':'read'}"'`);break;}
case '"'mark-all-read':mutate(ids.length?ids:filtered().map(m=>m.id),m=>({...m,unread:false}),'Marked as read');break;
case 'label':if("'!ids.length){toast('"'Select a conversation to add a label.');break;}state.menu='label';render();break;
case 'apply-label':{const label=el.dataset.label;const remove=ids.every(id=>state.mail.find(m=>m.id===id)?.labels.includes(label));mutate(ids,m=>({...m,labels:remove?m.labels.filter(l=>l"'!==label):[...new Set([...m.labels,label])]}),`${remove?'"'Removed':'Added'} label: "'${label}`);break;}
case '"'clock':if("'!ids.length){toast('"'Select a conversation to snooze.');break;}if(id)state.selected=new Set([id]);state.menu='snooze';render();break;
case 'snooze':state.open=null;mutate(ids,m=>({...m,folder:'snoozed',snoozedUntil:el.dataset.value}),"'`Snoozed until ${el.dataset.value.toLowerCase()}`);break;
case '"'undo':if(undoState){state.mail=undoState.mail;state.drafts=undoState.drafts;undoState=null;persist();render();toast('Action undone');}break;
case 'refresh':render();toast('You’re up to date');break;
case 'more':state.menu='more';render();break;
case 'account':state.menu=state.menu==='account'?null:'account';render();break;
case 'dismiss-menu':state.menu=null;render();break;
case 'help':case 'settings':case 'filters':case 'new-label':case 'storage':state.modal=action;state.menu=null;render();if(action==='new-label')"'$('"'#label-form input')?.focus();break;
case 'message-details':state.modal='details';render();break;
case 'dismiss-modal':state.modal=null;render();break;
case 'theme':state.settings.theme=el.dataset.value;persist();render();break;
case 'density':state.settings.density=el.dataset.value;persist();render();break;
case 'close-search':state.query='';state.page=0;render();break;
case 'unread-filter':state.unreadOnly="'!state.unreadOnly;state.page=0;state.selected.clear();render();break;
case '"'menu':state.drawer="'!state.drawer;render();break;
case '"'previous-page':state.page=Math.max(0,state.page-1);render();break;
case 'next-page':state.page++;render();break;
